import java.util.List;

record Graph(int vertexCount, List<Edge> edges) {
    Graph {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("Vertex count must be non-negative.");
        }
        if (edges == null) {
            throw new IllegalArgumentException("Edges must not be null.");
        }

        edges = List.copyOf(edges);
        validateEdges(vertexCount, edges);
    }

    static Graph fromEdgeMatrix(int vertexCount, int[][] rawEdges) {
        if (rawEdges == null) {
            throw new IllegalArgumentException("Edges must not be null.");
        }

        return new Graph(vertexCount, java.util.Arrays.stream(rawEdges)
            .map(Edge::fromMatrixRow)
            .toList());
    }

    private static void validateEdges(int vertexCount, List<Edge> edges) {
        for (Edge edge : edges) {
            validateVertex(edge.from(), vertexCount);
            validateVertex(edge.to(), vertexCount);
        }
    }

    private static void validateVertex(int vertex, int vertexCount) {
        if (vertex < 0 || vertex >= vertexCount) {
            throw new IllegalArgumentException(
                "Vertex " + vertex + " is out of bounds for graph with " + vertexCount + " vertices."
            );
        }
    }
}

final class KruskalMST {
    private static final MinimumSpanningTreeSolver SOLVER = new KruskalMinimumSpanningTreeSolver();

    private KruskalMST() {
        // Compatibility facade.
    }

    public static int kruskalsMST(int vertexCount, int[][] rawEdges) {
        return SOLVER.minimumSpanningTreeCost(Graph.fromEdgeMatrix(vertexCount, rawEdges));
    }

    static int minimumSpanningTreeCost(Graph graph) {
        return SOLVER.minimumSpanningTreeCost(graph);
    }

    static MinimumSpanningTreeResult findMinimumSpanningTree(Graph graph) {
        return SOLVER.findMinimumSpanningTree(graph);
    }
}

record Edge(int from, int to, int weight) implements Comparable<Edge> {
    Edge {
        // No per-edge validation here; Graph validates vertices against its size.
    }

    static Edge fromMatrixRow(int[] row) {
        if (row == null || row.length != 3) {
            throw new IllegalArgumentException("Each edge must contain exactly three values: from, to, weight.");
        }
        return new Edge(row[0], row[1], row[2]);
    }

    @Override
    public int compareTo(Edge other) {
        return Integer.compare(weight, other.weight);
    }
}

import java.util.ArrayList;
import java.util.List;

final class KruskalMinimumSpanningTreeSolver implements MinimumSpanningTreeSolver {
    @Override
    public MinimumSpanningTreeResult findMinimumSpanningTree(Graph graph) {
        if (graph == null) {
            throw new IllegalArgumentException("Graph must not be null.");
        }

        List<Edge> sortedEdges = graph.edges().stream()
            .sorted()
            .toList();

        DisjointSet disjointSet = new DisjointSet(graph.vertexCount());
        List<Edge> selectedEdges = new ArrayList<>();
        int totalWeight = 0;

        for (Edge edge : sortedEdges) {
            if (disjointSet.union(edge.from(), edge.to())) {
                selectedEdges.add(edge);
                totalWeight += edge.weight();
                if (selectedEdges.size() == graph.vertexCount() - 1) {
                    break;
                }
            }
        }

        return new MinimumSpanningTreeResult(
            totalWeight,
            selectedEdges,
            graph.vertexCount() == 0 || selectedEdges.size() == graph.vertexCount() - 1
        );
    }
}

final class KruskalMstDemo {
    private KruskalMstDemo() {
        // Demo entry point only.
    }

    public static void main(String[] args) {
        int[][] edges = {
            {0, 1, 10},
            {1, 3, 15},
            {2, 3, 4},
            {2, 0, 6},
            {0, 3, 5}
        };

        MinimumSpanningTreeResult result = KruskalMST.findMinimumSpanningTree(Graph.fromEdgeMatrix(4, edges));
        System.out.println(result.totalWeight());
        System.out.println(result.isConnected());
    }
}

interface MinimumSpanningTreeSolver {
    MinimumSpanningTreeResult findMinimumSpanningTree(Graph graph);

    default int minimumSpanningTreeCost(Graph graph) {
        return findMinimumSpanningTree(graph).totalWeight();
    }
}

